import random
from decimal import Decimal
import _legacy_pricing_check as old
import pricing as new

random.seed(1)
PRICES = [0, 1, 10, 12.99, "3.33", "0.005", 19.995, Decimal("7.777"), "1e3", 123456789.123456789, "bad", None]
QTYS = [-2, 0, 1, 2, 9, 10, 11, 25, 1.5, None, "3"]
CATS = [None, "books", "food", "default", "toys", "", 5, ["x"]]
TIERS = [None, "silver", "platinum", "bronze", "", 3, ["x"]]
COUPONS = [None, "WELCOME5", "HALFSHIP", "PCT10", "PCT50", "PCT", "PCT-5", "NOPE"]

def run(f, *a):
    try:
        r = f(*a)
        return ("ok", repr(r["total"]), [(l["sku"], repr(l["net"]), repr(l["tax"])) for l in r["lines"]], list(r.keys()))
    except Exception as e:
        return ("err", type(e).__name__)

def rand_item(i):
    it = {"sku": f"S{i}", "price": random.choice(PRICES), "qty": random.choice(QTYS)}
    if random.random() < 0.8:
        it["category"] = random.choice(CATS)
    if random.random() < 0.03:
        del it["price"]
    if random.random() < 0.03:
        del it["sku"]
    return it

n = 0
for _ in range(60000):
    cart = [rand_item(i) for i in range(random.randint(0, 4))]
    cust = {} if random.random() < 0.3 else {"tier": random.choice([t for t in TIERS if t != "gold"])}
    if random.random() < 0.05:
        cust = {"tier": "silver", "extra": 1}
    coupon = random.choice(COUPONS)
    a = run(old.checkout, cart, cust, coupon)
    b = run(new.checkout, cart, cust, coupon)
    if a != b:
        print("MISMATCH", cart, cust, coupon, a, b)
        raise SystemExit(1)
    n += 1
print("identical over", n, "random cases")

# gold: same as silver/platinum behaviour with 12%
cart = [{"sku": "A", "price": "10.00", "qty": 2}, {"sku": "B", "price": "3.33", "qty": 10, "category": "books"}]
g = new.checkout(cart, {"tier": "gold"})
for l in g["lines"]: print("gold", l["sku"], l["net"], l["tax"])
print("gold total", g["total"])
assert new.price_line({"sku": "X", "price": 100, "qty": 1}, {"tier": "gold"})["net"] == Decimal("88.00")
assert new.price_line({"sku": "X", "price": 100, "qty": 0}, {"tier": "gold"}) is None
print("gold ok")
